import falcon
from falcon import testing

class ResourceWithOnRequest:
    def on_request(self, req, resp):
        if req.method == 'GET':
            resp.text = 'GET'
        elif req.method == 'POST':
            resp.text = 'POST'

def test_bug():
    app = falcon.App()
    app.router_options.default_to_on_request = True
    app.add_route('/test', ResourceWithOnRequest())

    client = testing.TestClient(app)
    response = client.simulate_options('/test')
    assert response.headers.get('Allow') != ''
